VALUES (
  'seedex_loan-origination', 'loan-origination', 'Loan origination', 'A multi-team loan process with real task timings — find the team that gates throughput.',
  'A loan application flows across several teams with real per-task processing
times and approval branches (imported from the BPSim example).

